import{_ as s,c as e,o as i,ag as t}from"./chunks/framework.B-aGGnuW.js";const k=JSON.parse('{"title":"Configure the system","description":"","frontmatter":{},"headers":[],"relativePath":"installation/configure-system.md","filePath":"installation/configure-system.md","lastUpdated":1792149212000}'),n={name:"installation/configure-system.md"};function l(o,a,h,p,r,d){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="configure-the-system" tabindex="-1">Configure the system <a class="header-anchor" href="#configure-the-system" aria-label="Permalink to &quot;Configure the system&quot;">​</a></h1><p>Use <code>nano</code> to edit files: Ctrl+O followed by Enter saves, and Ctrl+X exits.</p><h2 id="hostname" tabindex="-1">Hostname <a class="header-anchor" href="#hostname" aria-label="Permalink to &quot;Hostname&quot;">​</a></h2><p>Replace <code>myhostname</code> with your computer&#39;s name:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myhostname</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/hostname</span></span></code></pre></div><h2 id="locale-and-keyboard" tabindex="-1">Locale and keyboard <a class="header-anchor" href="#locale-and-keyboard" aria-label="Permalink to &quot;Locale and keyboard&quot;">​</a></h2><p>Edit <code>/etc/locale.gen</code> and uncomment the UTF-8 locales you need, including <code>en_US.UTF-8</code> if using the example below:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/locale.gen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">locale-gen</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LANG=en_US.UTF-8</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/locale.conf</span></span></code></pre></div><p>Set your console keymap before generating the initramfs. This example uses German; choose the layout you used in the live ISO:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> KEYMAP=de-latin1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/vconsole.conf</span></span></code></pre></div><p>Desktop keyboard layouts are configured separately after login.</p><h2 id="time-and-networking" tabindex="-1">Time and networking <a class="header-anchor" href="#time-and-networking" aria-label="Permalink to &quot;Time and networking&quot;">​</a></h2><p>Replace <code>Region/City</code> with your timezone, for example <code>Europe/Berlin</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/share/zoneinfo/Region/City</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/localtime</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hwclock</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --systohc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd-timesyncd.service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NetworkManager.service</span></span></code></pre></div><p>NetworkManager handles the installed system&#39;s network connections. Wi-Fi credentials from the ISO are not copied automatically; connect again after reboot.</p><h2 id="pacman" tabindex="-1">Pacman <a class="header-anchor" href="#pacman" aria-label="Permalink to &quot;Pacman&quot;">​</a></h2><p>Edit <code>/etc/pacman.conf</code>. For Steam or other software requiring 32-bit libraries, uncomment both lines of the multilib repository:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[multilib]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = /etc/pacman.d/mirrorlist</span></span></code></pre></div><p>Optionally enable <code>Color</code> and set <code>ParallelDownloads = 5</code> in the options section. After changing repositories, perform a full upgrade:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Syu</span></span></code></pre></div><p>Avoid partial upgrades such as refreshing databases and installing packages without upgrading the system. See <a href="https://wiki.archlinux.org/title/System_maintenance" target="_blank" rel="noreferrer">System maintenance</a>.</p>`,21)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
